svg.metadata:
flowchart TB
  A["reldb.tx.wrap: begin transaction"]
  B["Read and write through the callback tx"]
  C["Inspect each HaiResult.success"]
  D["All succeed: return normally"]
  E["Attempt commit; return its outcome"]
  X["Operation fails: throw; attempt rollback and return failure"]
  A --> B
  B --> C
  C -->|"success=true"| D
  D --> E
  C -->|"success=false"| X
  B -->|"throws"| X
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class E good;
  class X stop;
